"use strict";
// A lock that settles from file system callbacks, as a lock file package does:
// taking it makes a directory, releasing it removes the directory, and the
// release promise resolves with undefined.
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
let taken = 0;
let released = 0;
exports.lock = (file, options) =>
  new Promise((resolve, reject) => {
    const dir = path.join(os.tmpdir(), `${path.basename(file)}.${process.pid}.lock`);
    fs.mkdir(dir, (err) => {
      if (err) return reject(err);
      taken++;
      resolve(
        () =>
          new Promise((done, failed) => {
            fs.rmdir(dir, (e) => {
              if (e) return failed(e);
              released++;
              done();
            });
          }),
      );
    });
  });
exports.counts = () => ({ taken, released });
